window.T18_DASHBOARD_UNITS = [{"unit":1,"theme":"almond – bold","cards":[{"w":"almond","p":"n.","d":"the oval edible nutlike seed of the almond tree, used in cooking or sweets","c":"杏仁（可數/不可數）","s":"My grandmother baked a batch of delicious almond cookies for the festive family gathering.","t":"我祖母為節日家庭聚會烤了一批美味的杏仁餅乾。"},{"w":"alphabet","p":"n.","d":"a set of letters or symbols in a fixed order used for writing a language","c":"字母系統；字母表（可數）","s":"The kindergarten teacher patiently taught the young children to recite the alphabet from A to Z.","t":"幼兒園老師耐心地教導幼童從 A 到 Z 背誦字母表。"},{"w":"apart","p":"adv.","d":"separated by a distance; into pieces or parts","c":"分開地；相距；成碎片","s":"The loving couple felt lonely when they had to live apart in different countries for their careers.","t":"這對相愛的情侶因各自的職業必須在不同國家分隔兩地生活時感到孤單。"},{"w":"set apart from","p":"v.phr.","d":"to distinguish or make someone or something noticeably different from others","c":"使…與眾不同；使脫穎而出","s":"Her exceptional dedication and creative thinking truly set her apart from other applicants during the interview.","t":"她非凡的專注力與創造性思維在面試期間確實讓她脫穎而出／與眾不同。"},{"w":"bait","p":"n./v.","d":"food used to entice fish or other animals into a trap; to entice or lure","c":"餌；誘餌；裝餌誘惑（名詞/動詞）","s":"The cunning detective laid a clever trap, and the arrogant thief foolishly took the bait.","t":"那位狡猾的偵探設下了一個巧妙陷阱，而自大的竊賊愚蠢地上鉤中計了。"},{"w":"bare","p":"adj.","d":"not clothed or covered; basic or simple; without extras","c":"赤裸的；光禿的；勉強的","s":"Walking along the cool sandy beach with bare feet brought a pleasant feeling of total relaxation.","t":"赤著雙腳在涼爽的沙灘上漫步帶來了一種徹底放鬆的愉悅感受。"},{"w":"bare one's teeth","p":"v.phr.","d":"to uncover one's teeth, especially in anger or hostility","c":"露出牙齒（露出凶相）","s":"When the wandering stranger stepped into the yard, the guard dog angrily bared its teeth and growled loudly.","t":"當那名徘徊的陌生人走進院子時，看門狗憤怒地露出牙齒並大聲低吼。"},{"w":"barn","p":"n.","d":"a large farm building used for storing grain or housing livestock","c":"穀倉；牲口棚（可數）","s":"The busy farmers worked together to move all the farm animals into the sturdy barn before the winter blizzard arrived.","t":"勤勞的農民們合力在冬季暴風雪來臨前將所有農場牲畜趕進堅固的牲口棚／穀倉內。"},{"w":"barrel","p":"n.","d":"a large cylindrical container, traditionally made of wooden staves and hoops","c":"木桶；一桶之量；槍管（可數）","s":"Premium red wine is carefully aged in charred French oak barrels for several years to develop its rich flavor.","t":"頂級紅酒在燒烤過的法國橡木桶中悉心陳釀數年，以發展出濃郁風味。"},{"w":"bold","p":"adj.","d":"showing an ability to take risks; confident and courageous; distinct","c":"大膽勇敢的；醒目的；粗體的","s":"The ambitious young entrepreneur made a bold decision to invest all her savings into renewable energy technology.","t":"那位雄心勃勃的年輕創業家做了一個大膽的決定，將所有積蓄投資於再生能源科技。"}]},{"unit":2,"theme":"bomb – confusion","cards":[{"w":"bomb","p":"n./v.","d":"a container filled with explosive material; to attack with bombs","c":"炸彈；轟炸（名詞/動詞）","s":"The police evacuated the busy subway station after receiving an anonymous bomb threat over the telephone.","t":"警方在接到一通匿名電話的炸彈威脅後，疏散了繁忙的地鐵站。"},{"w":"cabin","p":"n.","d":"a small wooden shelter or house; the passenger compartment in an aircraft or ship","c":"小木屋；機艙；客艙（可數）","s":"Our family rented a cozy log cabin in the quiet pine forest to spend our winter ski vacation.","t":"我們全家在安靜的松樹林中租了一間舒適的原木小木屋來度過冬季滑雪假期。"},{"w":"cable","p":"n./v.","d":"a thick rope of wire or fiber used for construction, electricity, or television","c":"電纜；纜繩；有線電視；拍電報","s":"Tourists can ride a scenic cable car all the way up to the mountain peak to enjoy panoramic ocean views.","t":"遊客可以搭乘風景優美的纜車一路直達山頂，欣賞壯麗的全景海景。"},{"w":"cafeteria","p":"n.","d":"a restaurant in which customers serve themselves or are served from a counter","c":"自助餐廳；學生餐廳（可數）","s":"Students gather in the noisy school cafeteria at noon every day to enjoy warm and nutritious lunches together.","t":"學生們每天中午聚集在喧鬧的學校自助餐廳裡，一同享用溫熱且營養的午餐。"},{"w":"cave","p":"n.","d":"a natural underground chamber in a hillside or cliff","c":"洞穴；山洞（可數）","s":"When the tour boat sailed slowly near the rocky cliff, passengers marveled at the spectacular natural sea cave.","t":"當遊覽船在岩石懸崖附近緩慢航行時，乘客們無不對壯麗的天然海蝕洞驚嘆不已。"},{"w":"cave in","p":"v.phr.","d":"to collapse inwards; to yield or surrender under pressure","c":"坍塌；塌陷；屈服讓步","s":"The determined union workers refused to cave in to pressure from management and continued their peaceful strike.","t":"堅定的工會勞工們拒絕屈服讓步於資方的壓力，並繼續進行和平罷工。"},{"w":"coach","p":"n./v.","d":"an athletic instructor; a comfortable long-distance bus; to train someone","c":"教練；長途巴士；訓練指導（名詞/動詞）","s":"The experienced head coach developed a brilliant defensive strategy that led the high school basketball team to victory.","t":"那位經驗豐富的總教練制定了一個絕妙的防守策略，帶領高中籃球隊贏得了勝利。"},{"w":"committee","p":"n.","d":"a group of people appointed for a specific function by a larger group","c":"委員會（可數）","s":"The city government decided to set up a special committee to address the serious issue of air pollution.","t":"市政府決定成立一個專門委員會來解決嚴重的空氣污染問題。"},{"w":"confuse","p":"v.","d":"to make someone bewildered or perplexed; to mistake one thing for another","c":"使困惑；使混亂；弄混（動詞）","s":"People often confuse the Australian opossum with the American possum because of their remarkably similar appearances.","t":"人們經常因為牠們極其相似的外表而將澳洲負鼠與美洲負鼠弄混／混淆。"},{"w":"confusion","p":"n.","d":"uncertainty about what is happening, intended, or required","c":"困惑；混亂（不可數）","s":"To avoid any unnecessary confusion among customers, the store manager put clear price tags on all promotional items.","t":"為了避免在顧客之間造成任何不必要的混淆困惑，店長在所有促銷商品上都貼上了清晰的價格標籤。"}]},{"unit":3,"theme":"dust – marvel","cards":[{"w":"dust","p":"n./v.","d":"fine, dry powder consisting of tiny particles of earth or waste; to clean dust off","c":"灰塵；塵土；除塵擦拭（名詞/動詞）","s":"The old library books had been left on the top shelf for years under a thick layer of dust.","t":"那些老舊的圖書館書籍在頂層書架上放置了多年，覆蓋著厚厚的一層灰塵。"},{"w":"fence","p":"n./v.","d":"a barrier enclosing an area of ground; to enclose with a fence; to practice swordplay","c":"柵欄；圍欄；擊劍（名詞/動詞）","s":"The farmer built a sturdy wooden fence around the apple orchard to keep wild rabbits and deer away.","t":"農夫在蘋果園周圍建造了一道堅固的木柵欄，以防止野兔和鹿靠近。"},{"w":"fighter","p":"n.","d":"a person who fights; a boxer; a fast military aircraft","c":"戰士；鬥士；戰鬥機（可數）","s":"The courageous young cancer patient remained a brave fighter throughout her long and difficult medical treatment.","t":"那位勇敢的年輕癌症病患在漫長而艱難的醫療過程中始終是一位堅強的鬥士。"},{"w":"firework","p":"n.","d":"a device containing gunpowder and other chemicals that explodes to produce lights and smoke","c":"煙火；煙花（通常複數 fireworks）","s":"Thousands of excited citizens gathered along the city harbor to watch the spectacular New Year fireworks display.","t":"數以千計興奮的市民聚集在城市港口，觀看壯麗的新年煙火表演。"},{"w":"helmet","p":"n.","d":"a hard or padded protective hat, worn by motorcyclists, soldiers, or sports players","c":"安全帽；頭盔（可數）","s":"Traffic laws strictly require all motorcycle riders to wear a protective helmet whenever traveling on public roads.","t":"交通法規嚴格要求所有機車騎士在行駛於公路上時必須佩戴防護性安全帽。"},{"w":"kilometer","p":"n.","d":"a metric unit of measurement equal to 1,000 meters (approx. 0.62 miles)","c":"公里；千米（可數，縮寫 km）","s":"The long-distance highway was completely clear, allowing cars to travel safely at one hundred kilometers per hour.","t":"長途公路上完全沒有堵車，允許汽車以每小時一百公里的速度安全行駛。"},{"w":"loose","p":"adj.","d":"not firmly or tightly fixed in place; not fitting tightly","c":"鬆動的；寬鬆的；散漫的","s":"The little boy was very excited because his front baby tooth became loose and was ready to fall out.","t":"那個小男孩非常興奮，因為他前面的乳牙變得鬆動了，隨時準備掉下來。"},{"w":"loosen","p":"v.","d":"to make or become less tight or firm; to relax one's grip or rules","c":"放鬆；鬆開；解開（動詞）","s":"Gentle stretching exercises before bed can effectively loosen up tight muscles and reduce physical stress.","t":"睡前做一些溫和的伸展運動可以有效放鬆緊繃的肌肉並減輕身體壓力。"},{"w":"marvelous","p":"adj.","d":"causing great wonder; extraordinary; extremely good","c":"絕妙的；令人驚嘆的；極好的","s":"The international orchestra delivered a truly marvelous performance that earned a standing ovation from everyone in the auditorium.","t":"這支國際交響樂團帶來了一場真正絕妙精彩的演出，贏得了音樂廳內全場觀眾的起立鼓掌。"},{"w":"marvel","p":"v./n.","d":"to be filled with wonder or astonishment; a wonderful or astonishing thing","c":"感到驚嘆；奇蹟；奇觀（動詞/名詞）","s":"Tourists from around the globe marvel at the breathtaking natural beauty and immense size of the Grand Canyon.","t":"來自全球各地的遊客無不對大峽谷令人屏息的自然之美與巨大規模驚嘆不已。"}]},{"unit":4,"theme":"novelist – stare","cards":[{"w":"novelist","p":"n.","d":"a person who writes novels","c":"小說家（可數）","s":"The famous novelist spent three full years conducting historical research before publishing her bestselling mystery book.","t":"那位著名小說家在出版她暢銷的懸疑著作之前，花了整整三年進行歷史研究。"},{"w":"onto","p":"prep.","d":"moving to a position on the surface of","c":"到…之上；向…之上","s":"The energetic young boy managed to climb onto the sturdy wooden fence to watch the soccer game.","t":"那個精力充沛的小男孩成功爬到了結實的木柵欄之上看足球賽。"},{"w":"passion","p":"n.","d":"strong and barely controllable emotion; intense enthusiasm for something","c":"熱情；熱愛；激情（不可數/可數）","s":"From a very young age, Maria had a deep passion for playing classical piano and composing original melodies.","t":"瑪麗亞從很小的時候就對彈奏古典鋼琴與創作原創旋律充滿了深刻的熱情。"},{"w":"passionate","p":"adj.","d":"showing or caused by strong feelings or a strong belief","c":"熱情的；熱烈的；激昂的","s":"The environmental activist gave a passionate speech that inspired hundreds of listeners to protect endangered wildlife.","t":"那位環保倡議者發表了一場熱情激昂的演說，激勵了數百名聽眾保護瀕危野生動物。"},{"w":"react","p":"v.","d":"to act in response to something; to undergo a chemical reaction","c":"作出反應；起化學反應；產生反響（動詞）","s":"How did the company employees react when the chief executive announced the unexpected holiday bonus?","t":"當執行長宣布發放意想不到的節日獎金時，公司員工作何反應？"},{"w":"reaction","p":"n.","d":"an action performed or a feeling experienced in response to a situation or event","c":"反應；回應；反作用（可數/不可數）","s":"When the alarm suddenly rang loudly in the dark hallway, my immediate reaction was to run toward the door.","t":"當走廊黑暗中警報突然響起時，我的第一直覺反應是衝向大門。"},{"w":"reasonable","p":"adj.","d":"having sound judgment; fair and sensible; not too expensive","c":"合理的；公道的；明理通達的","s":"The small family restaurant serves delicious homemade pasta and fresh garden salads at a very reasonable price.","t":"這家家庭小餐館以非常公道的價格提供美味的自製義大利麵與新鮮田園沙拉。"},{"w":"salary","p":"n.","d":"a fixed regular payment, typically paid on a monthly or annual basis","c":"薪水；月薪（固定薪資，可數/不可數）","s":"Although the startup offers a slightly lower initial salary, it provides wonderful health benefits and flexible working hours.","t":"雖然這家新創公司起初提供的薪水略低，但它提供了絕佳的健保福利與彈性工時。"},{"w":"significant","p":"adj.","d":"sufficiently great or important to be worthy of attention; noteworthy","c":"顯著重大的；意義深遠的","s":"Modern medical research has achieved significant progress in developing effective treatments for heart disease.","t":"現代醫學研究在開發心臟病有效治療方法方面取得了顯著重大的進展。"},{"w":"stare","p":"v./n.","d":"to look fixedly or vacantly at someone or something with one's eyes wide open","c":"凝視；盯著看（動詞/名詞）","s":"It is considered impolite to stare at people in public places, so try to avoid looking directly at strangers.","t":"在公共場所盯著他人看被認為是不禮貌的，因此盡量避免直視陌生人。"}]},{"unit":5,"theme":"starve – vehicle","cards":[{"w":"starve","p":"v.","d":"to suffer severely or die from hunger; to be extremely hungry","c":"挨餓；餓死（動詞）","s":"The trapped sailors survived on rainwater and biscuits so they would not starve on the desert island.","t":"受困的水手靠著雨水和餅乾存活，免於在荒島上挨餓／餓死。"},{"w":"sweat","p":"n./v.","d":"moisture exuded through the pores of the skin; to emit sweat","c":"汗水；流汗；辛苦工作（名詞/動詞）","s":"After completing a challenging five-kilometer run in the summer heat, Mark was completely covered in sweat.","t":"在夏日高溫下完成具挑戰性的五公里慢跑後，馬克滿身大汗。"},{"w":"technical","p":"adj.","d":"relating to a particular subject, art, or skill; requiring specialized knowledge","c":"技術的；專門性的；技術細節的","s":"If your home computer suddenly freezes or stops working, please call our 24-hour technical support hotline for help.","t":"如果您的家用電腦突然凍結或停止運作，請致電我們的二十四小時技術支援熱線尋求協助。"},{"w":"technique","p":"n.","d":"a way of carrying out a particular task, especially the execution of an artistic work","c":"技巧；技術；手法（可數/不可數）","s":"The professional yoga instructor taught her beginner students a calming breathing technique to relieve daily work stress.","t":"專業瑜珈教練向初學者傳授了一種平靜身心的呼吸技巧，以緩解日常工作壓力。"},{"w":"tough","p":"adj.","d":"strong enough to withstand adverse conditions; difficult to do; difficult to chew","c":"艱難的；堅韌的；咬不動的","s":"The school board of education had to make a very tough decision to cancel all outdoor sports events during the typhoon.","t":"教育委員會不得不做出一個非常艱難的決定，在颱風期間取消所有戶外體育賽事。"},{"w":"tug","p":"v./n.","d":"to pull something hard or suddenly; a hard, sudden pull","c":"用力拉；拽；拖船（動詞/名詞）","s":"Every year during the annual school sports day, students enthusiastically participate in a thrilling tug of war competition.","t":"每年學校校慶運動會期間，學生們都熱情地參加緊張刺激的拔河比賽。"},{"w":"twin","p":"n./adj.","d":"one of two children born at the same birth; forming a matching pair","c":"雙胞胎之一；成雙的；雙重的","s":"The hotel room was furnished with comfortable twin beds and an elegant desk for business travelers.","t":"飯店客房配有舒適的兩張單人床以及一張適合商務旅客的高雅辦公桌。"},{"w":"vehicle","p":"n.","d":"a thing used for transporting people or goods, especially on land","c":"車輛；交通工具；傳播媒介（可數）","s":"Drivers on the highway are legally required to pull over and yield to any flashing emergency vehicles.","t":"高速公路上的駕駛人依法必須靠邊停車，禮讓任何閃爍警示燈的緊急救援車輛。"}]}];
